 useEffect(()=>{if(!scanOpen)return;let stream=null,id=null,stopped=false;const start=async()=>{try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=document.getElementById('inventoryBarcodeVideo');if(!video)return;video.srcObject=stream;await video.play();const detector=new BarcodeDetector({formats:['ean_13','ean_8','code_128','upc_a','upc_e']});id=setInterval(async()=>{if(stopped)return;try{const codes=await detector.detect(video);if(codes[0]?.rawValue){setQ(codes[0].rawValue);setScanOpen(false)}}catch{}},500)}catch{setScanOpen(false);alert('تعذر تشغيل الكاميرا. تحقق من صلاحيتها.')}};start();return()=>{stopped=true;if(id)clearInterval(id);if(stream)stream.getTracks().forEach(t=>t.stop())}},[scanOpen]);
