 <div className="tableWrap"><table className="inventoryTable"><thead><tr><th>الباركود</th><th>اسم الدواء</th><th>الاسم العلمي</th><th>الصلاحية</th><th>الكمية</th><th>سعر النت (الشراء)</th><th>سعر المبيع (الصافي)</th><th>بطاقة المادة</th><th>حذف</th></tr></thead><tbody>{rows.map(r=><tr key={r.id} data-batch-id={r.id} className={r.expiry_date&&r.expiry_date<localDateKey(new Date())?'dangerRow':''}><td>{r.products?.barcode||'—'}</td><td><button className="linkButton" onClick={()=>openCard(r)}>{r.products?.name||'—'}</button><small>{r.products?.strength||''} {r.products?.dosage_form||''}</small></td><td>{r.products?.active_ingredient||'—'}</td><td>{r.expiry_date||'—'}</td><td><input className="qtyInput inventoryQty" type="number" min="0" value={r.quantity} onChange={e=>{const v=e.target.value;setRows(rs=>rs.map(x=>x.id===r.id?{...x,quantity:v}:x))}} onBlur={e=>editQty(r,e.target.value)}/></td><td>{money(r.purchase_price)} ل.س</td><td>{money(r.products?.sale_price)} ل.س</td><td><button className="iconBtn" title="بطاقة المادة" onClick={()=>openCard(r)}><FileText/></button></td><td><button className="iconBtn danger" title="حذف الدفعة" onClick={()=>removeBatch(r)} disabled={busy}><Trash2/></button></td></tr>)}</tbody></table>{!rows.length&&<div className="emptyCart">لا توجد دفعات مطابقة للبحث.</div>}</div>
