 const search=async(term='')=>{const t=String(term||'').trim();if(!t){setProducts([]);setErr('');return}setLoading(true);setErr('');try{const {data,error}=await supabase.rpc('admin_search_pos_products',{p_query:t,p_limit:30});if(error)throw error;setProducts(data||[])}catch(e){setProducts([]);setErr(e?.message||'تعذر البحث عن المنتج')}finally{setLoading(false)}};
