 const add=p=>{if(Number(p.stock)<=0)return alert('هذا المنتج لا يملك رصيداً متاحاً في المخزون');setCart(c=>{const x=c.find(i=>i.id===p.id);return x?c:[...c,{...p,part:posSettings.defaultPart,qty:posSettings.defaultQty}]});setProducts([]);setQ('')};
 const savePosSettings=()=>{const next={defaultQty:Math.max(0,Number(posSettings.defaultQty)||0),defaultPart:Math.max(0,Number(posSettings.defaultPart)||0)};setPosSettings(next);try{localStorage.setItem('pos_default_qty',String(next.defaultQty));localStorage.setItem('pos_default_part',String(next.defaultPart))}catch{}setSettingsOpen(false)};
 const openCard=async(p)=>{setCardProduct(p);setCardBatches(p.batches||[]);setCardLoading(true);try{const {data,error}=await supabase.from('batches').select('id,batch_number,expiry_date,quantity,purchase_price,received_date').eq('product_id',p.id).order('expiry_date',{ascending:true});if(!error)setCardBatches(data||[])}finally{setCardLoading(false)}};
