 const complete=async()=>{if(!cart.length)return;const items=cart.map(x=>({product_id:x.id,quantity:Number(x.qty||0)+(Number(x.part||0)/Math.max(1,Number(x.parts_per_unit||1))),unit_price:Number(x.sale_price||0)})).filter(x=>x.quantity>0);if(!items.length)return alert('أدخل كمية واحدة على الأقل');for(const it of items){const row=cart.find(x=>x.id===it.product_id);if(row&&it.quantity>Number(row.stock)+0.000001)return alert(`الكمية المطلوبة من «${row.name}» أكبر من الرصيد المتاح (${row.stock})`)}const {data,error}=await supabase.rpc('complete_sale_atomic',{p_items:items,p_discount:0,p_customer_id:null});if(error)alert(error.message);else{alert(`تم إتمام البيع بنجاح: ${String(data).slice(0,8)}`);setCart([]);search(q)}};
 const startScan=async()=>{if(!('BarcodeDetector' in window))return alert('هذا المتصفح لا يدعم BarcodeDetector. استخدم قارئ باركود USB أو أدخل الرقم يدوياً.');setScanOpen(true);try{const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});const video=document.getElementById('barcodeVideo');video.srcObject=stream;await video.play();const detector=new BarcodeDetector({formats:['ean_13','ean_8','code_128','upc_a','upc_e']});const loop=async()=>{if(!document.getElementById('barcodeVideo')){stream.getTracks().forEach(t=>t.stop());return}const codes=await detector.detect(video);if(codes[0]?.rawValue){setQ(codes[0].rawValue);setScanOpen(false);stream.getTracks().forEach(t=>t.stop())}};const id=setInterval(loop,500);setTimeout(()=>clearInterval(id),20000)}catch(e){setScanOpen(false);alert('تعذر تشغيل الكاميرا. تحقق من صلاحية الكاميرا.')}};
